package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;

/**
 * Rejects creating an owner that is identical to one already stored (same first name, last name,
 * address, city and telephone). Runs before {@link SaveOwner} so a duplicate never reaches the
 * data store; the thrown escalation maps to 409 Conflict.
 */
public class CheckDuplicateOwner {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateOwnerException {
        for (Owner existing : ownerRepository.findByLastName(owner.getLastName())) {
            if (Objects.equals(existing.getFirstName(), owner.getFirstName())
                    && Objects.equals(existing.getLastName(), owner.getLastName())
                    && Objects.equals(existing.getAddress(), owner.getAddress())
                    && Objects.equals(existing.getCity(), owner.getCity())
                    && Objects.equals(existing.getTelephone(), owner.getTelephone())) {
                throw new DuplicateOwnerException("An identical owner already exists");
            }
        }
    }
}

package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by {@code CheckDuplicateOwner} when a create request matches an owner that already
 * exists (same first name, last name, address, city and telephone). Handled globally by
 * {@link DuplicateOwnerExceptionHandler}, which responds 409 Conflict.
 */
public class DuplicateOwnerException extends Exception {

    public DuplicateOwnerException(String message) {
        super(message);
    }
}

